SELECT CASE WHEN w.entry_quality_score >= 70 THEN '70+' WHEN w.entry_quality_score >= 60 THEN '60-69' WHEN w.entry_quality_score >= 55 THEN '55-59' ELSE '50-54' END AS eq_band, CASE WHEN s.risk_reward_ratio < 0.5 THEN '<0.5' WHEN s.risk_reward_ratio < 1 THEN '0.5-1' ELSE '>=1' END AS rr_band, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(p.realized_pnl), 6) AS pnl_avg FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL AND p.opened_at BETWEEN '2026-10-09 00:00:00' AND '2026-10-19 18:00:00' GROUP BY eq_band, rr_band ORDER BY eq_band, rr_band LIMIT 30;